typedef struct SvPlayerUnk8F99 {
    // (the byte is cleared, then the bits 0..2 one by one)
    SvPlayerUnk8F99()
    {
        value = 0;
        for (s32 i = 0; i < 3; i++) {
            switch (i) {
            case 0:
                value &= ~1;
                break;
            case 1:
                value &= ~2;
                break;
            case 2:
                value &= ~4;
                break;
            }
        }
    }

    /* 0x0000 */ u8 value;
} SvPlayerUnk8F99;

