typedef struct SvCensusValue {
    /* 0x0000 */ u32 totalPlayerStat; // All player stats combined
    /* 0x0004 */ u32 playerStats[4]; // For each player

    // (inline; name is ours) everything 0
    void Clear()
    {
        totalPlayerStat = 0;
        playerStats[0] = 0;
        playerStats[1] = 0;
        playerStats[2] = 0;
        playerStats[3] = 0;
    }
} SvCensusValue;

